"""Interaction functions for the Decision to Adapt dialog in the Mosaiq application starting from Mosaiq 3.2.3"""

from .objects.mosaiq_decision_to_adapt_objects import DecisionToAdapt
from interops.libraries.squish_actions import CommonActions
from interops.libraries.squish_actions.exceptions import FailedToFindObject
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME


def __find_decision_to_adapt_dialog(waitTimeout: int = 5000) -> bool:
    """Searches for the Decision to Adapt dialog Window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the decision_to_adapt.py file context!

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Decision to Adapt dialog to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DecisionToAdapt.main_Window, waitTimeout) is not None else False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def check_decision_to_adapt_dialog(waitTimeout: int = 3) -> bool:
    """Check if Decision to Adapt dialog is dispalyed

    :param int waitTimeout: Amount of time to wait (in seconds) for the Decision to Adapt dialog to appear
    """
    return CommonActions.wait_for_object_to_appear(DecisionToAdapt.main_Window, waitTimeout)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_adapt_radio_button(waitTimeout: int = 3000) -> None:
    """
    Waits for the Decision to Adapt dialog to appear and clicks on the Adapt radio button.

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Decision to Adapt dialog to appear
    """
    try:
        if __find_decision_to_adapt_dialog(waitTimeout):
            CommonActions.left_click_object(DecisionToAdapt.adapt_Radio_Button)
    except FailedToFindObject:
        pass


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_do_not_adapt_radio_button(waitTimeout: int = 3000) -> None:
    """
    Waits for the Decision to Adapt dialog to appear and clicks on the Do Not Adapt radio button.

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Decision to Adapt dialog to appear
    """
    try:
        if __find_decision_to_adapt_dialog(waitTimeout):
            CommonActions.left_click_object(DecisionToAdapt.do_Not_Adapt_Radio_Button)
    except FailedToFindObject:
        pass


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_decision_to_adapt_continue_button(waitTimeout: int = 3000) -> None:
    """
    Waits for the Decision to Adapt dialog to appear and clicks on the Continue button.

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Decision to Adapt dialog to appear
    """
    try:
        if __find_decision_to_adapt_dialog(waitTimeout):
            CommonActions.left_click_object(DecisionToAdapt.continue_Button)
            CommonActions.wait_for_object_to_disappear(DecisionToAdapt.main_Window)
    except FailedToFindObject:
        pass